// rn registry 的注入式端口 —— rn-adapter.ts 只依赖这两个接口 + @swarm-hive/sdk,
// 让 adapter 本体可纯逻辑单测(不碰 expo-* 真实实现)。真实实现见同目录
// expo-downloader.ts / expo-installer.ts,由用户在装配时注入。
//
// 语义对齐 SwarmHive SDK 的 UpdateAdapter:
// - download 把远端 URL 落到本地,产出一个本地 APK 路径(string);
// - install 是 fire-and-forget handoff —— 把 APK 交给系统 PackageInstaller(via
//   ACTION_VIEW intent),intent 派发即 resolve(SDK engine 无 installing 态)。

/** 下载进度回调:累计已下载字节 + 期望总字节(任一为 0/未知时由 adapter 兜底 percent)。 */
export type ApkProgressCallback = (downloaded: number, total: number) => void;

/**
 * 一个候选产物的期望值,由 adapter 从 `ReleaseInfo` 取出(只有它手上有 release)。
 * `download` 用它校验投递并给落盘产物打标,`reconcile` 用它复检磁盘上的残留 ——
 * 同一组判据,所以是同一个类型。
 */
export interface ApkArtifactExpectation {
  /**
   * 该产物对应的版本标识(RN 用 versionCode 字符串)。下载器据它给落盘的产物打标,
   * 下次进程起来时才认得出「磁盘上这个包是给哪一版的」。
   */
  version: string;
  /** 期望字节数(来自 update 响应的 `size_bytes`);缺省则跳过尺寸校验。 */
  sizeBytes?: number;
}

/**
 * APK 下载器(注入式)。把 `url` 下到本地缓存,边下边回调进度,
 * resolve 出本地 APK 路径(供 installer 消费)。
 *
 * **契约:下载器的职责是产出一个可用的 APK,而不是产出一个文件。** resolve 之前必须确认
 * 拿到的确实是 APK —— `createDownloadResumable` 对非 2xx **不抛错**,它把错误响应体(如
 * OSS 的 XML 错误页)照常写进目标文件并正常 resolve。校验归下载器所有(它才碰 expo-*,
 * adapter 因此得以保持纯逻辑可单测),而 adapter 的多源 failover **只在下载器抛错时才
 * 触发** —— 所以一个不校验的实现会让 failover 对它本该扛住的故障静默失效。
 *
 * 自行注入实现时:要么直接用 expo-downloader.ts 的 `createExpoApkDownloader`,要么照它的
 * `assertApkDownload` 自行校验(状态 + 非空 + 尺寸 + ZIP magic,失败先删文件再抛)。
 */
export interface ApkDownloader {
  /**
   * 下载 `url` 到本地;`onProgress(downloaded,total)` 报进度;resolve 本地 APK 路径。
   * `expected` 用于校验投递结果并给落盘产物打标。
   */
  download(
    url: string,
    onProgress: ApkProgressCallback,
    expected: ApkArtifactExpectation,
  ): Promise<string>;
  /**
   * 可选:把上个进程留下的产物与候选对齐,喂给 SDK 的 `UpdateAdapter.reconcile`。
   *
   * - `expected` 非空且磁盘产物匹配且完整 → resolve 本地 APK 路径(可直接安装);
   * - `expected` 非空但不匹配/损坏 → 清理产物,resolve null;
   * - `expected` 为 null → 清理产物,resolve null。
   *
   * 实现**必须**在 resolve null 时把不再有用的残留删掉 —— 否则装过的包会永久占着缓存。
   */
  reconcile?(expected: ApkArtifactExpectation | null): Promise<string | null>;
}

/**
 * `install` 被门禁拦下的原因。UI 据此选择引导文案,无需依赖任何 expo-* 符号。
 *
 * 目前只有一种。写成联合类型是为了将来加原因时不必改判别方式 —— 但**不要预先加**一个
 * 产生不出来的取值:那会让 UI 长出一条永远走不到的分支,并让人以为已经有对应的引导了。
 */
export type ApkInstallBlockReason =
  /** app 不在前台 —— Android 10+ 会静默丢弃后台派发的 Activity 启动。 */
  "background";

/**
 * APK 安装器(注入式)。把本地 APK 交给系统安装器。
 *
 * **fire-and-forget handoff 语义**:install() 在安装 intent 派发后即 resolve —— 控制权
 * 已交给系统「安装新版本?」对话框,本 Promise **不**等待安装真正完成(Android 不允许
 * 第三方静默安装;用户确认后本进程会被替换,用户取消则下次 check 再弹)。
 *
 * 正因为 resolve 不代表任何结果,**派发前的门禁是这一层唯一能给出的真实信号**:
 * app 不在前台时**返回** `{ reason: "background" }` 而不是发一个必然被系统丢弃的 intent。
 * 返回而非抛错 —— 那不是失败,什么都没发生过(见 SDK `UpdateAdapter.install` 的说明)。
 * 调用方(SDK engine)可以反复重试同一个句柄,门禁不消耗产物。
 *
 * 「未授权安装未知应用」**刻意不做门禁**:`expo-intent-launcher` 不暴露
 * `canRequestPackageInstalls`,内建的探测只能靠猜,而一个错误的「已拒绝」会挡掉本来能装的
 * 更新。未授权时照常派发,Android 自己会把用户领到授权页 —— 授权后返回,ready 还在,
 * 点「立即安装」即可。这是一条通路,不是死路。
 */
export interface ApkInstaller {
  /**
   * 把本地 `apkPath` 交给系统 PackageInstaller;intent 派发即 resolve。
   * 前置门禁未过时返回 `{ reason }`(未派发任何 intent)。
   */
  // `void` 在这里正是要表达的语义 ——「要么什么都不返回,要么返回 blocked」。换成
  // `undefined` 会逼**每个**实现在最常见的那条路径上显式 `return undefined`,把规则的
  // 成本转嫁给所有实现方。
  // biome-ignore lint/suspicious/noConfusingVoidType: 理由见上。
  install(apkPath: string): Promise<void | { reason: ApkInstallBlockReason }>;
}

// rn-adapter —— UpdateAdapter 的 React Native / Expo Android 实现(shadcn registry 源码,
// 会被复制进用户项目)。
//
// 设计要点(对齐 tauri-adapter,见 add-registry-rn/design.md):
// - **本体只 import @swarm-hive/sdk**(+ 同 registry 的 ports.ts)。expo-file-system /
//   expo-intent-launcher / async-storage 的真实实现全部经 ports 注入(downloader /
//   installer / storage),让 adapter 可纯逻辑单测、且不绑定具体 expo 版本。
// - check 委托 SDK 的 checkUpdateAndroid(打 /api/v1/updates/android/:slug,统一 200 +
//   has_update 区分),**不**复用 Tauri 的 plugin-updater check。
// - compare 用 SDK 的 versionCodeComparator(整数 versionCode 比较)。
// - install 是 fire-and-forget handoff:把本地 APK 交给系统 PackageInstaller,**绝不
//   relaunch**(Tauri 才 relaunch;RN 由系统替换进程)。
//
// 依赖(本 registry item 的 npm dependencies,shadcn add 时自动安装):
//   @swarm-hive/sdk —— adapter 本体仅此一项;expo-* 真实实现走各自的 registry item。

import {
  type CheckContext,
  checkUpdateAndroid,
  type DownloadHandle,
  type KeyValueStorage,
  type Progress,
  type ReleaseInfo,
  type UpdateAdapter,
  versionCodeComparator,
} from "@swarm-hive/sdk";
import type { ApkDownloader, ApkInstaller } from "./ports";

/**
 * 下载进度 + 瞬时速度跟踪(500ms 节流)。搬自 tauri-adapter 的 DownloadSpeedTracker,
 * 改成累计式接口:RN 的 createDownloadResumable 回调直接给「已下载/总量」,
 * 故用 `update(downloaded,total)` 取代 Tauri 的 `started/progress(chunk)`。
 */
class DownloadSpeedTracker {
  private total = 0;
  private downloaded = 0;
  private lastEmitAt = 0;
  private lastEmitBytes = 0;
  private speed = 0;
  private emitted = false;

  constructor(
    private readonly onProgress: (p: Progress) => void,
    private readonly throttleMs = 500,
  ) {}

  /** 累计进度回调(downloaded/total 为累计绝对值)。首帧立即发,其后 500ms 节流。 */
  update(downloaded: number, total: number): void {
    this.downloaded = downloaded;
    this.total = total;
    const now = Date.now();
    if (!this.emitted) {
      this.lastEmitAt = now;
      this.lastEmitBytes = downloaded;
      this.emit();
      return;
    }
    const dt = now - this.lastEmitAt;
    if (dt >= this.throttleMs) {
      this.speed = ((this.downloaded - this.lastEmitBytes) * 1000) / dt;
      this.lastEmitAt = now;
      this.lastEmitBytes = this.downloaded;
      this.emit();
    }
  }

  /** 下载完成收口:服务端没给 total 时用已下载量兜底,保证最终 percent = 1。 */
  finish(): void {
    if (this.total === 0) this.total = this.downloaded;
    this.emit(1);
  }

  private emit(percentOverride?: number): void {
    this.emitted = true;
    const percent = percentOverride ?? (this.total > 0 ? this.downloaded / this.total : 0);
    this.onProgress({
      downloaded: this.downloaded,
      total: this.total,
      percent,
      speed: this.speed || undefined,
    });
  }
}

export interface RnAdapterOptions {
  /** SwarmHive server base URL(如 https://hive.example.com)。 */
  baseUrl: string;
  /** App slug。 */
  appSlug: string;
  /** 当前 versionName(显示用;透传给 endpoint 的 current_version_name)。 */
  currentVersionName: string;
  /** 设备 ABI(arm64-v8a / armeabi-v7a / x86_64);缺省让 server 走 fat APK/单产物兜底。 */
  abi?: string;
  /** 可选 channel;缺省走 app 默认 channel。 */
  channel?: string;
  /** APK 下载器(注入;真实实现见 expo-downloader.ts)。 */
  downloader: ApkDownloader;
  /** APK 安装器(注入;真实实现见 expo-installer.ts)。 */
  installer: ApkInstaller;
  /** KV 持久化(注入;真实实现见 storage.ts)。 */
  storage: KeyValueStorage;
  /** 注入 fetch(测试/RN polyfill);默认全局 fetch,透传给 checkUpdateAndroid。 */
  fetchImpl?: typeof fetch;
}

/**
 * 创建 RN/Expo Android 平台的 UpdateAdapter。
 *
 * - check:把 SDK 的 `CheckContext.currentVersion`(engine 里是 versionCode 的字符串形式)
 *   转 Number 当 currentVersionCode,clientId 透传,委托 `checkUpdateAndroid`。
 * - download:用注入的 downloader 下 `release.url`,DownloadSpeedTracker 产出 SDK Progress,
 *   payload = 本地 APK 路径(string)。
 * - install:把 payload(APK 路径)交给注入的 installer,fire-and-forget,**不 relaunch**。
 */
export function createRnAdapter(opts: RnAdapterOptions): UpdateAdapter {
  return {
    storage: opts.storage,
    compare: versionCodeComparator,

    async check(ctx: CheckContext): Promise<ReleaseInfo | null> {
      return checkUpdateAndroid({
        baseUrl: opts.baseUrl,
        appSlug: opts.appSlug,
        // engine 用 versionCode 的字符串形式存 currentVersion;转回整数喂 endpoint。
        currentVersionCode: Number(ctx.currentVersion),
        currentVersionName: opts.currentVersionName,
        abi: opts.abi,
        channel: opts.channel,
        clientId: ctx.clientId,
        fetchImpl: opts.fetchImpl,
      });
    },

    async download(
      release: ReleaseInfo,
      onProgress: (p: Progress) => void,
    ): Promise<DownloadHandle> {
      // 主源 + 备用源(GitHub Release,已过服务端 liveness/digest 校验)按序尝试:
      // 某源投递失败(OSS 匿名下 APK 受限的错误页 / 截断 / 网络错误)则逐个 fallback
      // (`add-github-release-source`)。
      //
      // 触发 fallback 的判据 = 注入的 downloader 抛错 —— 校验归下载器所有(碰 expo-* 的是
      // 它,本 adapter 因此保持纯逻辑可单测),这里只把期望值传下去。客户端 sha256 校验的
      // 要求已被撤销(`harden-rn-apk-downloader` design D5):Expo 没有廉价的流式 SHA-256、
      // 服务端在暴露镜像前已比对过 digest、传输损坏由尺寸 + ZIP magic 拦下、APK 真伪由
      // Android 安装器验签兜底。
      const candidates = [release.url, ...(release.mirrorUrls ?? [])].filter(
        (u, i, arr): u is string => !!u && arr.indexOf(u) === i,
      );
      let lastErr: unknown;
      for (const url of candidates) {
        const tracker = new DownloadSpeedTracker(onProgress);
        try {
          const apkPath = await opts.downloader.download(
            url,
            (downloaded, total) => {
              tracker.update(downloaded, total);
            },
            { sizeBytes: release.sizeBytes, version: artifactVersion(release) },
          );
          tracker.finish();
          // payload 存本地 APK 路径 —— self-contained 才能被 install 反复消费,
          // 也才能在下个进程里由 reconcile 重建出来。
          return { release, payload: apkPath };
        } catch (e) {
          lastErr = e;
        }
      }
      throw lastErr ?? new Error("no download source available");
    },

    // biome-ignore lint/suspicious/noConfusingVoidType: 见 ports.ts 上同名方法的说明。
    async install(handle: DownloadHandle): Promise<void | { reason: string }> {
      const apkPath = handle.payload;
      if (typeof apkPath !== "string" || !apkPath) {
        throw new Error("no downloaded APK path — call download() before install()");
      }
      // fire-and-forget handoff:交给系统 PackageInstaller,intent 派发即 resolve。
      // **绝不 relaunch** —— RN 由系统替换进程,用户确认后旧进程被新版本接管。
      // 可能被同一个 handle 反复调用(engine 的 ready 是持久静止态),installer 自身幂等。
      // 门禁挡下时 installer 返回 `{reason}`,原样透传给 engine —— 它只存不解释。
      return opts.installer.install(apkPath);
    },

    // 产物恢复:上个进程下完的 APK 还躺在缓存里就直接复用,让 engine 跳过整个下载阶段。
    // 注入的 downloader 没实现 reconcile 时**整个成员省略**(而不是给一个恒 null 的函数)
    // —— engine 据 `adapter.reconcile` 是否存在决定走不走复用路径,给了函数就等于宣称
    // 「我管产物」,却每次都判失效,反而会把句柄清掉。
    reconcile: opts.downloader.reconcile
      ? async (release: ReleaseInfo | null): Promise<DownloadHandle | null> => {
          const expectation = release
            ? { version: artifactVersion(release), sizeBytes: release.sizeBytes }
            : null;
          const apkPath = await opts.downloader.reconcile?.(expectation);
          return apkPath && release ? { release, payload: apkPath } : null;
        }
      : undefined,
  };
}

/**
 * 产物的版本标识 —— 落盘时打的标,下个进程据它认出「磁盘上这个包是给哪一版的」。
 * RN 的更新闸门以 `versionCode` 为主键(见 SDK 的 versionCodeComparator),缺失时才退回
 * 显示版本号。
 */
function artifactVersion(release: ReleaseInfo): string {
  return release.versionCode != null ? String(release.versionCode) : release.version;
}

import * as FileSystem from "expo-file-system/legacy";
import * as IntentLauncher from "expo-intent-launcher";
import { AppState, Platform } from "react-native";
import type { ApkInstallBlockReason, ApkInstaller } from "./ports";

/** android.content.Intent#FLAG_GRANT_READ_URI_PERMISSION */
const FLAG_GRANT_READ_URI_PERMISSION = 0x00000001;
/** android.content.Intent#FLAG_ACTIVITY_NEW_TASK */
const FLAG_ACTIVITY_NEW_TASK = 0x10000000;

/** iOS / 非 Android 平台不支持 in-app 安装(由 TestFlight / App Store 接管)。 */
export class ApkInstallNotSupportedOnIosError extends Error {
  constructor() {
    super("In-app APK install is not supported on iOS");
    this.name = "ApkInstallNotSupportedOnIosError";
  }
}

/**
 * 创建方案 A 的 ApkInstaller。install(apkPath):
 *   前台门禁 → file:// 路径 → getContentUriAsync →
 *   ACTION_VIEW(package-archive)→ 系统 PackageInstaller。
 * intent 派发即 resolve(fire-and-forget);非 Android 抛 ApkInstallNotSupportedOnIosError。
 *
 * **前台门禁是本文件存在的主要理由。** Android 10+ 禁止后台启动 Activity:app 不在前台时
 * 派发的安装 intent 会被系统**静默丢弃**(不抛异常、不回调,只在 logcat 留一行
 * `Background activity launch blocked!`),而 `startActivityAsync` 照常 resolve。于是 UI
 * 显示「等待系统确认」而系统那边什么都没发生 —— 这正是 SwarmDrop v0.12.3 熄屏更新时
 * 用户被卡死的原因。宁可不发并回一个可判别的 reason,让调用方留在 ready 稍后重试。
 *
 * ⚠️ **本文件由 `@swarmhive-rn` registry 分发,上游在 SwarmHive
 * `packages/registry-rn/registry/rn/lib/expo-installer.ts`。要改请改上游再重新拉取。**
 */
export function createExpoApkInstaller(): ApkInstaller {
  return {
    // biome-ignore lint/suspicious/noConfusingVoidType: 见 ports.ts 上同名方法的说明。
    async install(apkPath: string): Promise<void | { reason: ApkInstallBlockReason }> {
      if (Platform.OS !== "android") {
        throw new ApkInstallNotSupportedOnIosError();
      }
      // 返回而非抛错:门禁挡下不是失败,什么都没发生过、产物完好。抛错会让 engine 进 error
      // 并广播一个假故障,逼每个订阅者去认识这个平台错误类再把状态推回来。
      if (AppState.currentState !== "active") {
        return { reason: "background" };
      }

      // expo-file-system 自带 FileProvider:把本地 file:// 转成可对外授权的 content:// URI。
      const contentUri = await FileSystem.getContentUriAsync(apkPath);
      await IntentLauncher.startActivityAsync("android.intent.action.VIEW", {
        data: contentUri,
        type: "application/vnd.android.package-archive",
        flags: FLAG_GRANT_READ_URI_PERMISSION | FLAG_ACTIVITY_NEW_TASK,
      });
      // 不等安装结果:控制权已交给系统对话框(fire-and-forget handoff)。
      //
      // **未授权「安装未知应用」时也照发**:Android 自己会把用户领到授权页,授权后返回,
      // engine 仍在 ready,点「立即安装」即可。做一个只能靠猜的权限探测反而会挡掉本来
      // 能装的更新,见 ports.ts 的 ApkInstallBlockReason。
    },
  };
}

import type { KeyValueStorage } from "@swarm-hive/sdk";
import * as FileSystem from "expo-file-system/legacy";
import { Platform } from "react-native";
import type { ApkArtifactExpectation, ApkDownloader, ApkProgressCallback } from "./ports";

/** iOS / 非 Android 平台不支持下载安装 APK。 */
export class ApkDownloadNotSupportedOnIosError extends Error {
  constructor() {
    super("APK download is not supported on iOS");
    this.name = "ApkDownloadNotSupportedOnIosError";
  }
}

/** 已落盘且校验通过的产物记录 —— 「磁盘上这个包是给哪一版的」。 */
const ARTIFACT_KEY = "swarmhive.apk_artifact";

/** 落盘产物的身份 —— 「磁盘上这个包是给哪一版的」。尺寸不存:复检时的期望值由候选
 *  release 提供,存一份旧的只会在服务端改了 size_bytes 时给出更差的判断。 */
interface ArtifactRecord {
  version: string;
  path: string;
}

export interface ExpoDownloaderOptions {
  /** KV 持久化 —— 断点存档与产物记录都存这里。与 adapter 用同一份实例。 */
  storage: KeyValueStorage;
  /** 缓存文件名,默认 swarmhive-update.apk(放在 FileSystem.cacheDirectory 下)。 */
  fileName?: string;
}

function getHeader(headers: Record<string, string> | undefined, name: string): string | undefined {
  if (!headers) return undefined;
  const needle = name.toLowerCase();
  for (const [key, value] of Object.entries(headers)) {
    if (key.toLowerCase() === needle) return value;
  }
  return undefined;
}

async function readTextPreview(uri: string): Promise<string> {
  try {
    const text = await FileSystem.readAsStringAsync(uri, {
      encoding: FileSystem.EncodingType.UTF8,
    });
    return text.replace(/\s+/g, " ").slice(0, 160);
  } catch {
    return "";
  }
}

/**
 * APK 本质是 ZIP。OSS / CDN 错误页经常是 200 + XML/HTML —— downloadAsync 不抛错、状态也
 * 是 2xx,只有内容能识破。同一份判据在完成校验与 `reconcile` 复检里共用。
 */
async function hasZipMagic(uri: string): Promise<boolean> {
  const magic = await FileSystem.readAsStringAsync(uri, {
    encoding: FileSystem.EncodingType.Base64,
    position: 0,
    length: 4,
  });
  return magic.startsWith("UEs");
}

/**
 * 校验投递结果确实是一个完整的 APK,否则抛错(抛错即触发 adapter 的换源 fallback)。
 * 顺序:状态 → 非空 → 尺寸 → ZIP magic;尺寸是 O(1) 的 getInfoAsync,排在要读字节的
 * magic 之前。`expected.sizeBytes` 缺省时跳过尺寸这层,其余照常。
 */
async function assertApkDownload(
  result: FileSystem.FileSystemDownloadResult,
  expected: ApkArtifactExpectation,
): Promise<void> {
  if (result.status < 200 || result.status >= 300) {
    const contentType = getHeader(result.headers, "content-type");
    const preview = await readTextPreview(result.uri);
    throw new Error(
      `APK download returned HTTP ${result.status}${contentType ? ` (${contentType})` : ""}${
        preview ? `: ${preview}` : ""
      }`,
    );
  }

  const info = await FileSystem.getInfoAsync(result.uri);
  if (!info.exists || info.size < 4) {
    throw new Error("APK download produced an empty file");
  }

  // 截断投递:连接中断后 downloadAsync 照常 resolve,残缺文件的 ZIP magic 仍然合法,
  // 只有尺寸能发现。
  if (expected.sizeBytes != null && info.size !== expected.sizeBytes) {
    throw new Error(
      `APK download is truncated: expected ${expected.sizeBytes} bytes, got ${info.size}`,
    );
  }

  if (!(await hasZipMagic(result.uri))) {
    const contentType = getHeader(result.headers, "content-type");
    const preview = await readTextPreview(result.uri);
    throw new Error(
      `Downloaded file is not an APK${contentType ? ` (${contentType})` : ""}${
        preview ? `: ${preview}` : ""
      }`,
    );
  }
}

/**
 * 创建方案 A 的 ApkDownloader。
 *
 * `download(url, onProgress, expected?)`:
 *   清残留 → 全量下到 cacheDirectory → 校验是完整 APK → 记下产物版本 → resolve 本地
 *   `file://` 路径。校验失败先删残留文件与记录(不留毒化缓存)再抛。
 *   **不做断点续传** —— expo 的 resumeData 只有 pauseAsync 能产出,进程被杀时拿不到,
 *   理由见 download 内部注释。
 *
 * `reconcile(expected)`:把磁盘产物与候选对齐 —— 命中返回路径(SDK 据此跳过整个下载
 *   阶段),否则清理并返回 null。
 *
 * 非 Android 抛 `ApkDownloadNotSupportedOnIosError`。
 *
 * ⚠️ **本文件由 `@swarmhive-rn` registry 分发,上游在 SwarmHive
 * `packages/registry-rn/registry/rn/lib/expo-downloader.ts`。要改请改上游再重新拉取**
 * —— 就地改会在下次拉取时被覆盖,且改动不会回流给其它 app。
 *
 * 这条声明刻意放在 JSDoc 而非文件头 banner:shadcn 拉取时会**剥掉 banner**,放那里等于
 * 只有上游看得见、下游看不见 —— 而下游正是需要看到它的人。上下游倒置(上游自称下游的
 * 镜像)曾让下游加的 APK 校验没有回流义务,registry 于是给每个新装配的 app 发了一个不
 * 设防的下载器,把 OSS 的 XML 错误页当 APK 喂给系统安装器(见 harden-rn-apk-downloader)。
 */
export function createExpoApkDownloader(opts: ExpoDownloaderOptions): ApkDownloader {
  const { storage } = opts;
  const fileName = opts.fileName ?? "swarmhive-update.apk";

  function targetPath(): string {
    const cacheDir = FileSystem.cacheDirectory;
    if (!cacheDir) throw new Error("FileSystem.cacheDirectory unavailable");
    return `${cacheDir}${fileName}`;
  }

  async function readArtifact(): Promise<ArtifactRecord | null> {
    const raw = await storage.get(ARTIFACT_KEY);
    if (!raw) return null;
    try {
      return JSON.parse(raw) as ArtifactRecord;
    } catch {
      return null;
    }
  }

  /** 删文件 + 抹掉记录。产物失效的唯一收口,避免漏删其中一样。 */
  async function discardArtifact(path: string): Promise<void> {
    await FileSystem.deleteAsync(path, { idempotent: true });
    await storage.set(ARTIFACT_KEY, "");
  }

  return {
    async download(
      url: string,
      onProgress: ApkProgressCallback,
      expected: ApkArtifactExpectation,
    ): Promise<string> {
      if (Platform.OS !== "android") {
        throw new ApkDownloadNotSupportedOnIosError();
      }
      const target = targetPath();

      // 清掉上次残留的 partial 文件。
      //
      // **这里刻意不做断点续传。** expo 的 `DownloadResumable` 看起来支持它,实际不行:
      // `resumeData` 只在 `pauseAsync()` 里被赋值(`this.resumeData = pauseResult.resumeData`),
      // 而 `savable()` 只是把当前字段读出来。进程被杀时没有任何钩子能替我们调 pauseAsync,
      // 所以「下载开始前存 savable、下次用它 resume」存下来的 resumeData 恒为 undefined ——
      // 原生层收到空 resumeData 不会带 Range 头,反而会 truncate 目标文件,等于从头下,
      // 只是多留了个残留文件和一份假装有用的存档。
      //
      // 真要做需要 AppState 切后台时 pauseAsync + 立刻 resumeAsync 来刷出真实的 resumeData,
      // 那会打断后台下载(而「熄屏也要能下完」正是这套流程的诉求),得不偿失。
      // **已下载完成**的产物跨进程复用由 `reconcile` 负责,那条路是真的有效。
      await FileSystem.deleteAsync(target, { idempotent: true });

      const resumable = FileSystem.createDownloadResumable(url, target, {}, (p) => {
        // 累计绝对值直接透传给 adapter 的 DownloadSpeedTracker(它负责节流 + percent)。
        onProgress(p.totalBytesWritten, p.totalBytesExpectedToWrite);
      });

      const result = await resumable.downloadAsync();
      if (!result?.uri) {
        throw new Error("Download produced no file");
      }

      try {
        await assertApkDownload(result, expected);
      } catch (error) {
        await discardArtifact(result.uri);
        throw error;
      }

      const record: ArtifactRecord = { version: expected.version, path: result.uri };
      await storage.set(ARTIFACT_KEY, JSON.stringify(record));
      return result.uri;
    },

    async reconcile(expected: ApkArtifactExpectation | null): Promise<string | null> {
      if (Platform.OS !== "android") return null;

      const record = await readArtifact();
      if (!record) {
        // 没有记录 ⇒ 没有可复用的产物。仍扫一遍固定路径:记录可能因存储清理丢了,
        // 文件却还占着缓存(端口契约要求返回 null 时不留无用残留)。
        await FileSystem.deleteAsync(targetPath(), { idempotent: true });
        return null;
      }
      if (!expected || record.version !== expected.version) {
        await discardArtifact(record.path);
        return null;
      }

      // 复检与下载完成时同一套判据:存在 → 尺寸 → ZIP magic。记录可能是上个进程写的,
      // 中间隔着一次系统缓存清理或用户手动删文件,不能只信记录。
      const info = await FileSystem.getInfoAsync(record.path);
      const usable =
        info.exists &&
        (expected.sizeBytes == null || info.size === expected.sizeBytes) &&
        (await hasZipMagic(record.path));
      if (!usable) {
        await discardArtifact(record.path);
        return null;
      }
      return record.path;
    },
  };
}

// storage —— KeyValueStorage 的 RN 实现,包 @react-native-async-storage/async-storage
// (草稿,需 RN 运行时验证;本仓 vitest 用注入的 mock storage 替代)。
//
// SDK engine 用它持久化 client_id / dismiss-TTL / lastCheckedAt(对齐 tauri-adapter 用
// plugin-store 的角色)。
//
// 依赖:@react-native-async-storage/async-storage。

import AsyncStorage from "@react-native-async-storage/async-storage";
import type { KeyValueStorage } from "@swarm-hive/sdk";

/**
 * 创建 AsyncStorage 支撑的 KeyValueStorage。get 把 AsyncStorage 的 string | null
 * 直接透传(契约一致);set 落盘。
 */
export function createAsyncStorage(): KeyValueStorage {
  return {
    async get(key: string): Promise<string | null> {
      return AsyncStorage.getItem(key);
    },
    async set(key: string, value: string): Promise<void> {
      await AsyncStorage.setItem(key, value);
    },
  };
}
